SELECT DISTINCT a.scene_id, a.scene_name, a.scene_desc, a.scene_type, a.scene_status, a.catalog_item_id, a.created_time, a.updated_time, a.creator_id, a.updator_id, a.remark, a.prologue, (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS "creatorName", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName", brpr.publish_status AS "beyondPublishStatus" FROM bt_bot_scene a LEFT JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.scene_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'BOT' AND brpr.status_cd = '00A' AND brpr.tenant_id = #{query.tenantId} WHERE a.status_cd = '00A'
AND a.scene_name LIKE
#{query.searchContent}
AND a.scene_status = #{query.sceneStatus}
AND a.scene_status IN (#{sceneStatus})
AND brpr.publish_status = #{query.beyondPublishStatus}
AND a.tenant_id = #{query.tenantId} ORDER BY a.updated_time DESC

SELECT DISTINCT a.scene_id, a.scene_name, a.scene_desc, a.scene_type, a.scene_status, a.catalog_item_id, a.created_time, a.updated_time, a.creator_id, a.updator_id, a.remark, a.prologue, (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS "creatorName", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName", brpr.publish_status AS "beyondPublishStatus" FROM bt_bot_scene a LEFT JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.scene_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'AGENT' AND brpr.status_cd = '00A' AND brpr.tenant_id = #{query.tenantId} WHERE a.status_cd = '00A' AND a.tenant_id = #{query.tenantId}
AND a.scene_name LIKE
#{query.name}
AND a.scene_status = #{query.status}
AND brpr.publish_status = #{query.beyondPublishStatus}
ORDER BY a.updated_time DESC

SELECT a.scene_id, a.scene_name, a.scene_desc, a.scene_type, a.scene_status, a.catalog_item_id, a.created_time, a.updated_time, a.creator_id, a.updator_id, a.remark, a.prologue, (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS "creatorName", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName" FROM bt_bot_scene a WHERE a.status_cd = '00A'
AND a.scene_name LIKE
#{query.searchContent}
AND a.scene_type IN (#{sceneType})
AND a.scene_status = #{query.sceneStatus}
AND a.catalog_item_id = #{query.catalogItemId}
AND EXISTS (SELECT 1 FROM bt_bot_scene_rel b WHERE a.scene_id = b.scene_id AND a.tenant_id = b.tenant_id AND b.status_cd = '00A' AND b.bot_id = #{query.botId})
AND a.tenant_id = #{query.tenantId} ORDER BY a.updated_time DESC

